function inject(){let e,t,n=document.getElementById("injectable-header"),d=document.getElementById("injectable-footer");fetch("/base/header.html").then(e=>e.text()).then(t=>{e=t,n.innerHTML=e}),fetch("/base/footer.html").then(e=>e.text()).then(e=>{t=e,d.innerHTML=t})}document.addEventListener("DOMContentLoaded",inject);